// Replace with your own policy wording (one chunk per item), or fetch it from storage.
const docs = [
 {"document_type":"auto_policy","source":"PAP-2026 Section II - Collision","line":"auto","text":"We will pay for direct and accidental loss to your covered auto caused by collision with another object or by overturn, less the deductible shown in the Declarations. Collision coverage applies whether or not you are at fault."},
 {"document_type":"auto_policy","source":"PAP-2026 Section III - Comprehensive","line":"auto","text":"We will pay for direct and accidental loss to your covered auto not caused by collision, including fire, theft, vandalism, falling objects, hail, flood and contact with a bird or animal. Glass breakage is covered under this section."},
 {"document_type":"auto_policy","source":"PAP-2026 Exclusions","line":"auto","text":"We do not provide coverage for loss caused by wear and tear, mechanical or electrical breakdown, freezing, or road damage to tires unless damage results from a covered theft. No coverage applies while the auto is used for ride-share or delivery for hire unless the Commercial Use endorsement is attached."},
 {"document_type":"auto_policy","source":"PAP-2026 Duties After Loss","line":"auto","text":"You must give us prompt notice of the accident or loss, including how, when and where it happened. Theft or vandalism must be reported to the police within 48 hours. Failure to cooperate may result in denial of the claim."},
 {"document_type":"home_policy","source":"HO3-2026 Section I - Perils Insured","line":"property","text":"We insure the dwelling against direct physical loss unless excluded. Sudden and accidental discharge of water from a plumbing, heating or air-conditioning system is covered, including the cost of tearing out and replacing part of the building to repair the system."},
 {"document_type":"home_policy","source":"HO3-2026 Section I - Exclusions","line":"property","text":"We do not cover loss caused by flood, surface water, earth movement, gradual seepage or leakage over 14 days or more, neglect, or mold unless the mold results from a covered water loss. Wear and tear and deterioration are excluded."},
 {"document_type":"home_policy","source":"HO3-2026 Section I - Wind and Hail","line":"property","text":"Windstorm and hail damage to the roof and exterior is covered subject to the separate wind/hail deductible of 2 percent of Coverage A. Interior damage is covered only if wind or hail first creates an opening in the roof or wall."},
 {"document_type":"claims_guideline","source":"Claims Handling Guideline CG-7","line":"all","text":"Claims with estimated severity above 0.7, suspected fraud indicators, injuries, or policies with a lapse in the last 30 days must be referred to a senior adjuster. Adjusters must document the policy provision relied on for every coverage decision."}
];
return docs.map(d => ({ json: { ...d, tenant_id: null } }));

parameters.query:
INSERT INTO policy_documents (tenant_id, document_type, source, line_of_business, chunk_text, embedding, active)
VALUES (NULLIF($1, ''), $2, $3, $4, $5, $6::vector, true)
ON CONFLICT (source) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, active = true, updated_at = now();
